using System;
using System.IO;
using System.Text;
using System.Diagnostics;
using System.Windows.Forms;
using System.Runtime.InteropServices;
using System.Threading;

namespace OneNotesApp
{
    public class Program
    {
        private const string HTML_B64 = "";

        public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);

        [DllImport("user32.dll")]
        public static extern bool EnumWindows(EnumWindowsProc enumProc, IntPtr lParam);

        [DllImport("user32.dll")]
        public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);

        [DllImport("user32.dll")]
        public static extern int GetClassName(IntPtr hWnd, StringBuilder lpString, int nMaxCount);

        [DllImport("dwmapi.dll")]
        public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int attrValue, int attrSize);

        [DllImport("user32.dll")]
        public static extern bool SetWindowText(IntPtr hWnd, string text);

        [STAThread]
        public static void Main()
        {
            try
            {
                string tempDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "ONENotes");
                if (!Directory.Exists(tempDir))
                {
                    Directory.CreateDirectory(tempDir);
                }

                // Dedicated isolated user data dir prevents sharing Edge dark profile
                string userDataDir = Path.Combine(tempDir, "EdgeProfile");
                if (!Directory.Exists(userDataDir))
                {
                    Directory.CreateDirectory(userDataDir);
                }

                string htmlFile = Path.Combine(tempDir, "app.html");
                byte[] htmlBytes = Convert.FromBase64String(HTML_B64);
                File.WriteAllBytes(htmlFile, htmlBytes);

                string[] browserCandidates = new string[]
                {
                    Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles) + @"\Microsoft\Edge\Application\msedge.exe",
                    Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86) + @"\Microsoft\Edge\Application\msedge.exe",
                    Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles) + @"\Google\Chrome\Application\chrome.exe",
                    Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86) + @"\Google\Chrome\Application\chrome.exe",
                    Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData) + @"\Google\Chrome\Application\chrome.exe"
                };

                string selectedBrowser = null;
                foreach (var b in browserCandidates)
                {
                    if (File.Exists(b))
                    {
                        selectedBrowser = b;
                        break;
                    }
                }

                if (selectedBrowser != null)
                {
                    ProcessStartInfo psi = new ProcessStartInfo();
                    psi.FileName = selectedBrowser;
                    // Passing separate user-data-dir with light mode flag and window-size
                    psi.Arguments = "--app=\"" + htmlFile + "\" --user-data-dir=\"" + userDataDir + "\" --window-size=1200,800";
                    psi.UseShellExecute = false;
                    Process.Start(psi);

                    // Continuous polling via EnumWindows to catch the top-level window handle
                    ThreadPool.QueueUserWorkItem((state) =>
                    {
                        bool found = false;
                        for (int attempt = 0; attempt < 50; attempt++)
                        {
                            Thread.Sleep(120);
                            EnumWindows((hWnd, lParam) =>
                            {
                                StringBuilder classSb = new StringBuilder(256);
                                GetClassName(hWnd, classSb, 256);
                                string className = classSb.ToString();

                                if (className == "Chrome_WidgetWin_1")
                                {
                                    StringBuilder titleSb = new StringBuilder(256);
                                    GetWindowText(hWnd, titleSb, 256);
                                    string title = titleSb.ToString();

                                    if (title.Contains("ONE Notes") || title.Contains("app.html") || title.Length <= 1)
                                    {
                                        // 1. Remove title text completely
                                        SetWindowText(hWnd, "");

                                        // 2. Set DWM Titlebar Color to White (0x00FFFFFF)
                                        int captionColor = 0x00FFFFFF;
                                        DwmSetWindowAttribute(hWnd, 35, ref captionColor, sizeof(int));

                                        // 3. Set DWM Text / Button Color to Black (0x00000000)
                                        int textColor = 0x00000000;
                                        DwmSetWindowAttribute(hWnd, 36, ref textColor, sizeof(int));

                                        found = true;
                                        return false; // Stop enumeration
                                    }
                                }
                                return true;
                            }, IntPtr.Zero);

                            if (found) break;
                        }
                    });
                }
                else
                {
                    Process.Start(htmlFile);
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Failed to launch ONE Notes: " + ex.Message, "ONE Notes Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
    }
}
